// Flowise Custom Tool get_sap_inventory (generated by flowise/scinsight/build-scinsight.cjs)
// Read-only SAP stock by batch (synthetic S/4HANA snapshot): usable vs excluded stock (expired, QA blocked, reserved, in inspection), expiry dates. Filter by item and/or location.
// SCInsight allowlisted tool: GET /api/v1/sap/inventory (fixed endpoint; key from Flowise Variables, never from the model)
const fetch = require('node-fetch');
const base = String($vars.sci_api_url || '').replace(/\/+$/, '');
const key = String($vars.sci_agent_key || '');
if (!base || !key) return JSON.stringify({ error: 'configuration', detail: 'Flowise variables sci_api_url and sci_agent_key are required' });
const args = {};
let item_id = typeof $item_id === 'undefined' || $item_id === null ? '' : String($item_id).trim();
item_id = item_id.toUpperCase();
if (/^(none|null|undefined|n\/a)?$/i.test(item_id)) item_id = '';
if (item_id && !/^[A-Z0-9][A-Z0-9_-]{1,40}$/.test(item_id)) return JSON.stringify({ error: 'invalid_argument', detail: 'item_id has an invalid format: ' + item_id.slice(0, 40) });
if (item_id) args.item_id = item_id;
let location = typeof $location === 'undefined' || $location === null ? '' : String($location).trim();
location = location.toUpperCase();
if (/^(none|null|undefined|n\/a)?$/i.test(location)) location = '';
if (location && !/^[A-Z0-9][A-Z0-9_-]{1,40}$/.test(location)) return JSON.stringify({ error: 'invalid_argument', detail: 'location has an invalid format: ' + location.slice(0, 40) });
if (location) args.location = location;
let url = base + "/api/v1/sap/inventory";
const qs = ["item_id","location"].filter((k) => args[k] !== undefined).map((k) => k + '=' + encodeURIComponent(args[k])).join('&');
if (qs) url += '?' + qs;
const options = { method: 'GET', headers: { 'X-API-Key': key, 'Content-Type': 'application/json', Accept: 'application/json' } };
let res;
try { res = await fetch(url, options); } catch (e) { return JSON.stringify({ error: 'unreachable', detail: String(e && e.message || e).slice(0, 200) }); }
const text = await res.text();
let data;
try { data = JSON.parse(text); } catch (e) { data = { detail: text.slice(0, 500) }; }
if (!res.ok) return JSON.stringify({ error: 'http_' + res.status, detail: data.detail || data });
// keep the answer inside the model context: drop record-level lineage, keep the snapshot id
const strip = (o) => Array.isArray(o) ? o.map(strip) : (o && typeof o === 'object') ? Object.fromEntries(Object.entries(o).filter(([k]) => k !== 'source_records' && k !== 'provenance').map(([k, v]) => [k, strip(v)])) : o;
const out = strip(data);
if (data && data.provenance) out.snapshot_id = data.provenance.snapshot_id;
const json = JSON.stringify(out);
return json.length > 9000 ? json.slice(0, 9000) + ' ...[truncated: call a narrower query]' : json;
